import { Injectable, ServiceUnavailableException } from '@nestjs/common';

export interface ClinicalArtifactRequest {
  documentType:
    'REPORT' | 'REPORT_ADDENDUM' | 'EPISODE_EXPORT' | 'JUNTA_DECISION';
  contentSha256: string;
  content: Record<string, unknown>;
  signer: {
    professionalId: string;
    name: string;
    council: string;
  };
  minimumSignatureLevel: 'ADVANCED' | 'QUALIFIED';
}

export interface ClinicalArtifactReceipt {
  contentSha256: string;
  storageDocumentId: string;
  artifactSha256: string;
  signatureLevel: 'ADVANCED' | 'QUALIFIED';
  signatureFormat: 'PAdES-TSA';
  signedAt: string;
  tsaTime: string;
  certificateValidationSource: 'OCSP' | 'CRL';
  certificateValidationStatus: 'GOOD';
  certificateValidatedAt: string;
}

function isHexSha256(value: unknown): value is string {
  return typeof value === 'string' && /^[0-9a-f]{64}$/u.test(value);
}

interface ClinicalTrustConfiguration {
  signingUrl: string;
  healthUrl: string;
  token: string;
}

function isNonLocalProfile(): boolean {
  const profile =
    process.env.DETRAN_RUNTIME_PROFILE ??
    (process.env.NODE_ENV === 'test' ? 'test' : 'local-sandbox');
  return profile === 'staging-like' || profile === 'production';
}

function validatedUrl(
  name: string,
  value: string,
  requireHttps: boolean,
): string {
  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    throw new ServiceUnavailableException(`${name} is not a valid URL`);
  }
  if (requireHttps && parsed.protocol !== 'https:') {
    throw new ServiceUnavailableException(
      `${name} must use HTTPS outside local/test`,
    );
  }
  return value;
}

export function clinicalTrustConfiguration(): ClinicalTrustConfiguration {
  const signingUrl = process.env.DETRAN_CLINICAL_SIGNING_URL;
  const healthUrl = process.env.DETRAN_CLINICAL_SIGNING_HEALTH_URL;
  const token = process.env.DETRAN_CLINICAL_SIGNING_TOKEN;
  if (!signingUrl || !healthUrl || !token) {
    throw new ServiceUnavailableException(
      'Clinical PAdES signing service is not configured; trust readiness is unavailable',
    );
  }
  const requireHttps = isNonLocalProfile();
  return {
    signingUrl: validatedUrl(
      'DETRAN_CLINICAL_SIGNING_URL',
      signingUrl,
      requireHttps,
    ),
    healthUrl: validatedUrl(
      'DETRAN_CLINICAL_SIGNING_HEALTH_URL',
      healthUrl,
      requireHttps,
    ),
    token,
  };
}

/** Fail-closed adapter for the platform-managed PDF/A + PAdES/TSA service. */
@Injectable()
export class PadesSigningHttpAdapter {
  async checkCapabilities(): Promise<void> {
    const configuration = clinicalTrustConfiguration();
    const response = await fetch(configuration.healthUrl, {
      headers: { authorization: `Bearer ${configuration.token}` },
      signal: AbortSignal.timeout(5_000),
    });
    if (!response.ok) {
      throw new ServiceUnavailableException(
        `Clinical trust readiness failed with HTTP ${response.status}`,
      );
    }
    const capabilities = (await response.json()) as {
      pades?: unknown;
      tsa?: unknown;
      lta?: unknown;
      certificateValidation?: unknown;
    };
    if (
      capabilities.pades !== true ||
      capabilities.tsa !== true ||
      capabilities.lta !== true ||
      !Array.isArray(capabilities.certificateValidation) ||
      !capabilities.certificateValidation.some((source) =>
        ['OCSP', 'CRL'].includes(String(source)),
      )
    ) {
      throw new ServiceUnavailableException(
        'Clinical trust service lacks required PAdES-TSA/LTA/OCSP-or-CRL capabilities',
      );
    }
  }

  async renderAndSign(
    request: ClinicalArtifactRequest,
  ): Promise<ClinicalArtifactReceipt> {
    const configuration = clinicalTrustConfiguration();
    const response = await fetch(configuration.signingUrl, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${configuration.token}`,
        'content-type': 'application/json',
      },
      body: JSON.stringify(request),
      signal: AbortSignal.timeout(15_000),
    });
    if (!response.ok) {
      throw new ServiceUnavailableException(
        `Clinical PAdES signing failed with HTTP ${response.status}`,
      );
    }
    const receipt = (await response.json()) as Partial<ClinicalArtifactReceipt>;
    if (
      receipt.contentSha256 !== request.contentSha256 ||
      !isHexSha256(receipt.artifactSha256) ||
      !receipt.storageDocumentId ||
      receipt.signatureFormat !== 'PAdES-TSA' ||
      !['ADVANCED', 'QUALIFIED'].includes(receipt.signatureLevel ?? '') ||
      !receipt.signedAt ||
      !receipt.tsaTime ||
      !['OCSP', 'CRL'].includes(receipt.certificateValidationSource ?? '') ||
      receipt.certificateValidationStatus !== 'GOOD' ||
      !receipt.certificateValidatedAt
    ) {
      throw new ServiceUnavailableException(
        'Clinical PAdES signing returned an invalid evidence receipt',
      );
    }
    return receipt as ClinicalArtifactReceipt;
  }
}
import { Injectable, ServiceUnavailableException } from '@nestjs/common';

import {
  PEC_BIOMETRIC_PROCESSING_POLICY,
  type PecBiometricProcessingPurpose,
} from './biometric-processing-policy.js';

export interface BiometricVerificationRequest {
  providerCode: string;
  stationId: string;
  deviceCertificateFingerprint: string;
  captureReference: string;
  modality: 'FINGERPRINT' | 'FACE';
  kind: 'CHECKIN' | 'MEDICAL' | 'PSYCH';
  subjectReference: { patientId?: string; professionalId?: string };
}

export interface BiometricVerificationReceipt {
  passed: boolean;
  score: number | null;
  lfdScore: number | null;
  evidenceDocumentId: string;
  evidenceSha256: string;
  reason: string | null;
}

@Injectable()
export class BiometricVerificationHttpAdapter {
  async verify(
    request: BiometricVerificationRequest,
  ): Promise<BiometricVerificationReceipt> {
    const endpoint = process.env.DETRAN_BIOMETRIC_VERIFICATION_URL;
    const credential = process.env.DETRAN_BIOMETRIC_VERIFICATION_TOKEN;
    const processorContractId =
      process.env.DETRAN_BIOMETRIC_PROCESSOR_CONTRACT_ID;
    if (!endpoint || !credential || !processorContractId) {
      throw new ServiceUnavailableException(
        'Biometric verification provider and processor contract are not configured',
      );
    }
    const processingPurpose = this.processingPurpose(request);
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${credential}`,
        'content-type': 'application/json',
        'x-processing-contract-id': processorContractId,
        'x-processing-legal-basis': PEC_BIOMETRIC_PROCESSING_POLICY.legalBasis,
        'x-processing-purpose': processingPurpose,
      },
      body: JSON.stringify(request),
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
      throw new ServiceUnavailableException(
        `Biometric verification failed with HTTP ${response.status}`,
      );
    }
    const receipt =
      (await response.json()) as Partial<BiometricVerificationReceipt>;
    const validScore = (score: unknown) =>
      score === null ||
      (typeof score === 'number' && score >= 0 && score <= 100);
    if (
      typeof receipt.passed !== 'boolean' ||
      !validScore(receipt.score) ||
      !validScore(receipt.lfdScore) ||
      !receipt.evidenceDocumentId ||
      !receipt.evidenceSha256?.match(/^[0-9a-f]{64}$/u) ||
      (receipt.reason !== null && typeof receipt.reason !== 'string')
    ) {
      throw new ServiceUnavailableException(
        'Biometric provider returned an invalid evidence receipt',
      );
    }
    return receipt as BiometricVerificationReceipt;
  }

  private processingPurpose(
    request: BiometricVerificationRequest,
  ): PecBiometricProcessingPurpose {
    if (request.kind === 'CHECKIN' && request.subjectReference.patientId) {
      return PEC_BIOMETRIC_PROCESSING_POLICY.purposes.candidatePresence;
    }
    if (request.kind !== 'CHECKIN' && request.subjectReference.professionalId) {
      return PEC_BIOMETRIC_PROCESSING_POLICY.purposes.examinerAuthorship;
    }
    if (request.kind !== 'CHECKIN' && request.subjectReference.patientId) {
      return PEC_BIOMETRIC_PROCESSING_POLICY.purposes.candidatePresence;
    }
    throw new ServiceUnavailableException(
      'Biometric verification request has no valid processing purpose',
    );
  }
}
import { createHash } from 'node:crypto';
import { Injectable, ServiceUnavailableException } from '@nestjs/common';

export interface CouncilVerificationRequest {
  councilType: 'CRM' | 'CRP';
  councilNumber: string;
  councilState: string;
  professionalName: string;
}

export interface CouncilVerificationReceipt {
  professionalName: string | null;
  status: 'ACTIVE' | 'INACTIVE' | 'SUSPENDED';
  providerCheckedAt: string;
  responseSha256: string;
}

@Injectable()
export class CouncilVerificationHttpAdapter {
  async verify(
    request: CouncilVerificationRequest,
  ): Promise<CouncilVerificationReceipt> {
    const endpoint = process.env.DETRAN_COUNCIL_VERIFICATION_URL;
    const credential = process.env.DETRAN_COUNCIL_VERIFICATION_TOKEN;
    if (!endpoint || !credential) {
      throw new ServiceUnavailableException(
        'Professional council verification service is not configured',
      );
    }
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${credential}`,
        'content-type': 'application/json',
      },
      body: JSON.stringify(request),
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
      throw new ServiceUnavailableException(
        `Professional council verification failed with HTTP ${response.status}`,
      );
    }
    const raw = await response.text();
    let value: unknown;
    try {
      value = JSON.parse(raw);
    } catch {
      throw new ServiceUnavailableException(
        'Professional council verification returned malformed JSON',
      );
    }
    if (!value || typeof value !== 'object') {
      throw new ServiceUnavailableException(
        'Professional council verification returned an invalid receipt',
      );
    }
    const receipt = value as {
      active?: unknown;
      status?: unknown;
      professionalName?: unknown;
      checkedAt?: unknown;
    };
    if (
      typeof receipt.active !== 'boolean' ||
      (receipt.professionalName !== undefined &&
        receipt.professionalName !== null &&
        typeof receipt.professionalName !== 'string') ||
      (receipt.checkedAt !== undefined && typeof receipt.checkedAt !== 'string')
    ) {
      throw new ServiceUnavailableException(
        'Professional council verification returned an invalid receipt',
      );
    }
    const checkedAt = receipt.checkedAt ?? new Date().toISOString();
    if (Number.isNaN(new Date(checkedAt).valueOf())) {
      throw new ServiceUnavailableException(
        'Professional council verification returned an invalid check time',
      );
    }
    const normalizedStatus = String(receipt.status ?? '').toUpperCase();
    const status = receipt.active
      ? 'ACTIVE'
      : normalizedStatus.includes('SUSP')
        ? 'SUSPENDED'
        : 'INACTIVE';
    return {
      professionalName:
        typeof receipt.professionalName === 'string'
          ? receipt.professionalName
          : null,
      status,
      providerCheckedAt: checkedAt,
      responseSha256: createHash('sha256').update(raw).digest('hex'),
    };
  }
}
import assert from 'node:assert/strict';
